"use client";

import React, { useState } from "react";
import Image from "next/image";
import NextLink from "next/link";
import { motion } from "framer-motion";
import { Heart, Sparkles, Zap, ArrowUpRight, Gauge, Activity, GitCompare } from "lucide-react";
import { Vehicle } from "@/types/vehicle";
import { Button } from "@/components/ui/button";
import { Badge, SpecTag } from "@/components/ui/badge";
import { formatCurrency, formatHP } from "@/lib/utils";
import { cn } from "@/lib/utils";

export interface VehicleCardProps {
  vehicle: Vehicle;
  isComparing?: boolean;
  onToggleCompare?: (vehicleId: string) => void;
}

export const VehicleCard: React.FC<VehicleCardProps> = ({
  vehicle,
  isComparing = false,
  onToggleCompare,
}) => {
  const [isFavorite, setIsFavorite] = useState(false);
  const [imageLoaded, setImageLoaded] = useState(false);

  const fuelVariantMap: Record<string, "cyan" | "emerald" | "gold" | "crimson" | "slate"> = {
    Electric: "cyan",
    "Plug-in Hybrid": "emerald",
    Hybrid: "emerald",
    Petrol: "crimson",
    Diesel: "slate",
  };

  return (
    <motion.article
      initial={{ opacity: 0, y: 16 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
      className="group relative flex flex-col justify-between rounded-lg border border-white/[0.08] bg-[#090D15]/90 backdrop-blur-md overflow-hidden transition-all duration-300 hover:border-cyan-400/40 hover:shadow-[0_8px_30px_rgba(0,240,255,0.12)]"
    >
      {/* 1. Image Container with Badges & Action Overlays */}
      <div className="relative h-52 sm:h-56 w-full overflow-hidden bg-[#060910]">
        {/* Subtle Image Skeleton / Placeholder */}
        {!imageLoaded && (
          <div className="absolute inset-0 bg-white/[0.04] animate-pulse" />
        )}

        <Image
          src={vehicle.image}
          alt={`${vehicle.brand} ${vehicle.model} - ${vehicle.variant || ""}`}
          fill
          sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw"
          className={cn(
            "object-cover object-center transition-transform duration-700 ease-out group-hover:scale-105",
            imageLoaded ? "opacity-100" : "opacity-0"
          )}
          onLoad={() => setImageLoaded(true)}
          priority={vehicle.isFeatured}
        />

        {/* Dark Gradient Overlay for Readability */}
        <div className="absolute inset-0 bg-gradient-to-t from-[#090D15] via-transparent to-black/50" />

        {/* Top Floating Badges */}
        <div className="absolute top-3 left-3 right-3 flex items-center justify-between pointer-events-none">
          <div className="flex items-center gap-1.5 flex-wrap">
            <Badge
              variant={fuelVariantMap[vehicle.fuelType] || "cyan"}
              size="sm"
            >
              {vehicle.fuelType}
            </Badge>
            <Badge variant="outline" size="sm">
              {vehicle.bodyType}
            </Badge>
            {vehicle.isFeatured && (
              <Badge variant="gold" size="sm">
                Featured
              </Badge>
            )}
          </div>

          {/* Favorite Button */}
          <button
            type="button"
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              setIsFavorite(!isFavorite);
            }}
            aria-label={isFavorite ? `Remove ${vehicle.model} from favorites` : `Add ${vehicle.model} to favorites`}
            className="pointer-events-auto flex h-8 w-8 items-center justify-center rounded-full bg-[#06080C]/80 border border-white/[0.12] text-slate-300 backdrop-blur-md transition-colors hover:border-rose-400 hover:text-rose-400 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-400"
          >
            <Heart
              className={cn(
                "h-4 w-4 transition-transform active:scale-125",
                isFavorite && "fill-rose-500 text-rose-500"
              )}
            />
          </button>
        </div>

        {/* Bottom Image Overlay: Drivetrain / 0-60 Pill */}
        {vehicle.performance?.zeroToSixty && (
          <div className="absolute bottom-3 left-3 flex items-center gap-1.5">
            <span className="inline-flex items-center gap-1 rounded-xs bg-black/75 px-2 py-0.5 font-mono text-[10px] text-cyan-300 border border-white/[0.08] backdrop-blur-sm">
              <Zap className="h-3 w-3 text-cyan-400" />
              0-60: {vehicle.performance.zeroToSixty}s
            </span>
            <span className="inline-flex items-center rounded-xs bg-black/75 px-2 py-0.5 font-mono text-[10px] text-slate-300 border border-white/[0.08] backdrop-blur-sm">
              {vehicle.drivetrain}
            </span>
          </div>
        )}
      </div>

      {/* 2. Vehicle Content & Specs */}
      <div className="flex flex-col flex-1 p-5 space-y-4 justify-between">
        <div className="space-y-2">
          {/* Brand & Year Header */}
          <div className="flex items-center justify-between">
            <span className="font-mono text-xs uppercase tracking-widest text-cyan-400 font-semibold">
              {vehicle.brand} • {vehicle.year}
            </span>
            <span className="font-mono text-xs text-slate-400">
              {vehicle.transmission}
            </span>
          </div>

          {/* Model & Variant Title */}
          <NextLink
            href={`/explore/${vehicle.id}`}
            className="block group-hover:text-cyan-300 transition-colors"
          >
            <h3 className="text-xl font-bold tracking-tight text-white line-clamp-1">
              {vehicle.model}{" "}
              {vehicle.variant && (
                <span className="text-sm font-medium text-slate-400 font-sans">
                  {vehicle.variant}
                </span>
              )}
            </h3>
          </NextLink>

          {/* Price Readout */}
          <div className="flex items-baseline gap-1.5 pt-1">
            <span className="text-2xl font-extrabold text-white tracking-tight font-mono">
              {formatCurrency(vehicle.price)}
            </span>
            <span className="font-mono text-[11px] text-slate-400 uppercase">
              MSRP
            </span>
          </div>
        </div>

        {/* Key Telemetry Spec Ribbon */}
        <div className="grid grid-cols-3 gap-2 py-2.5 px-3 rounded-md bg-[#06080C]/80 border border-white/[0.05] text-center">
          <div className="space-y-0.5">
            <span className="block font-mono text-[9px] uppercase tracking-wider text-slate-400">
              POWER
            </span>
            <span className="block font-mono text-xs font-bold text-slate-200">
              {formatHP(vehicle.horsepower)}
            </span>
          </div>

          <div className="space-y-0.5 border-x border-white/[0.06]">
            <span className="block font-mono text-[9px] uppercase tracking-wider text-slate-400">
              TORQUE
            </span>
            <span className="block font-mono text-xs font-bold text-slate-200">
              {vehicle.torque} lb-ft
            </span>
          </div>

          <div className="space-y-0.5">
            <span className="block font-mono text-[9px] uppercase tracking-wider text-slate-400">
              {vehicle.fuelType === "Electric" ? "RANGE" : "EFFICIENCY"}
            </span>
            <span className="block font-mono text-xs font-bold text-cyan-300">
              {vehicle.fuelType === "Electric"
                ? `${vehicle.mileage} mi`
                : `${vehicle.mileage} mpg`}
            </span>
          </div>
        </div>

        {/* 3. Action Buttons: View Details & Compare */}
        <div className="flex items-center gap-2 pt-2 border-t border-white/[0.06]">
          <NextLink href={`/explore/${vehicle.id}`} className="flex-1">
            <Button
              variant="primary"
              size="sm"
              className="w-full text-xs uppercase tracking-wider font-semibold"
              rightIcon={<ArrowUpRight className="h-3.5 w-3.5" />}
            >
              View Details
            </Button>
          </NextLink>

          <Button
            variant={isComparing ? "luxury" : "outline"}
            size="sm"
            onClick={() => onToggleCompare?.(vehicle.id)}
            aria-label={`Compare ${vehicle.brand} ${vehicle.model}`}
            className={cn(
              "px-3 text-xs",
              isComparing && "border-amber-400 text-amber-300 bg-amber-950/40"
            )}
            leftIcon={<GitCompare className="h-3.5 w-3.5" />}
          >
            {isComparing ? "Added" : "Compare"}
          </Button>
        </div>
      </div>
    </motion.article>
  );
};

"use client";

import React, { useRef, useEffect } from "react";
import { Search, X } from "lucide-react";
import { cn } from "@/lib/utils";

export interface SearchBarProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  className?: string;
  totalMatches?: number;
}

export const SearchBar: React.FC<SearchBarProps> = ({
  value,
  onChange,
  placeholder = "Search by brand, model or vehicle...",
  className,
  totalMatches,
}) => {
  const inputRef = useRef<HTMLInputElement>(null);

  // Keyboard shortcut listener (Cmd+K or Ctrl+K / slash)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault();
        inputRef.current?.focus();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  return (
    <div className={cn("relative flex items-center w-full", className)}>
      <div className="absolute left-4 text-slate-400 pointer-events-none flex items-center justify-center">
        <Search className="h-4 w-4 text-cyan-400" />
      </div>

      <input
        ref={inputRef}
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        aria-label="Search vehicles"
        className={cn(
          "flex h-12 w-full rounded-lg border border-white/[0.10] bg-[#0A0E17] pl-11 pr-24 text-sm text-slate-100 placeholder:text-slate-500",
          "transition-all duration-200 focus:border-cyan-400 focus:bg-[#0D131F] focus:outline-none focus:ring-1 focus:ring-cyan-400/40",
          "shadow-[0_4px_20px_rgba(0,0,0,0.25)]"
        )}
      />

      <div className="absolute right-3 flex items-center gap-2">
        {value ? (
          <button
            type="button"
            onClick={() => onChange("")}
            aria-label="Clear search query"
            className="flex h-7 w-7 items-center justify-center rounded-full text-slate-400 hover:text-white hover:bg-white/[0.08] transition-colors"
          >
            <X className="h-4 w-4" />
          </button>
        ) : (
          <kbd className="hidden sm:inline-flex items-center gap-0.5 rounded border border-white/[0.12] bg-slate-800/80 px-2 py-0.5 text-[10px] font-mono font-semibold text-slate-400 select-none">
            <span>⌘</span>K
          </kbd>
        )}

        {totalMatches !== undefined && (
          <span className="hidden md:inline-flex font-mono text-[11px] text-cyan-400 font-semibold px-2 py-0.5 rounded-sm bg-cyan-950/60 border border-cyan-500/20">
            {totalMatches} Found
          </span>
        )}
      </div>
    </div>
  );
};

"use client";

import React from "react";
import { motion, AnimatePresence } from "framer-motion";
import { X, Filter, RotateCcw, Check, Sparkles } from "lucide-react";
import { VehicleBodyType, VehicleFilterOptions, VehicleFuelType, VehicleTransmission } from "@/types/vehicle";
import { Button } from "@/components/ui/button";
import { Slider } from "@/components/ui/slider";
import { Badge } from "@/components/ui/badge";
import { formatCurrency } from "@/lib/utils";
import { cn } from "@/lib/utils";
import { SPRING_TRANSITION } from "@/lib/motion";

export interface FilterSidebarProps {
  filters: VehicleFilterOptions;
  onChange: (filters: VehicleFilterOptions) => void;
  onReset: () => void;
  distinctBrands: string[];
  distinctBodyTypes: string[];
  distinctFuelTypes: string[];
  priceBounds: { min: number; max: number };
  hpBounds: { min: number; max: number };
  isMobileOpen: boolean;
  onCloseMobile: () => void;
  activeFilterCount: number;
}

export const FilterSidebar: React.FC<FilterSidebarProps> = ({
  filters,
  onChange,
  onReset,
  distinctBrands,
  distinctBodyTypes,
  distinctFuelTypes,
  priceBounds,
  hpBounds,
  isMobileOpen,
  onCloseMobile,
  activeFilterCount,
}) => {
  const currentMaxPrice = filters.maxPrice ?? priceBounds.max;
  const currentMinHp = filters.minHorsepower ?? hpBounds.min;

  // Filter content markup reusable between desktop and mobile drawer
  const filterContent = (
    <div className="space-y-6">
      {/* Header: Title & Reset Button */}
      <div className="flex items-center justify-between pb-4 border-b border-white/[0.08]">
        <div className="flex items-center gap-2">
          <Filter className="h-4 w-4 text-cyan-400" />
          <h3 className="font-mono text-sm uppercase tracking-wider font-bold text-white">
            FILTERS
          </h3>
          {activeFilterCount > 0 && (
            <Badge variant="cyan" size="sm">
              {activeFilterCount}
            </Badge>
          )}
        </div>

        {activeFilterCount > 0 && (
          <button
            type="button"
            onClick={onReset}
            className="inline-flex items-center gap-1 font-mono text-xs text-slate-400 hover:text-cyan-300 transition-colors"
          >
            <RotateCcw className="h-3 w-3" />
            Reset All
          </button>
        )}
      </div>

      {/* 1. Body Type */}
      <div className="space-y-2.5">
        <label className="block font-mono text-xs font-semibold text-slate-300 uppercase tracking-wider">
          Body Type
        </label>
        <div className="flex flex-wrap gap-1.5">
          <button
            type="button"
            onClick={() => onChange({ ...filters, bodyType: undefined })}
            className={cn(
              "px-2.5 py-1 rounded-sm text-xs font-mono transition-colors",
              !filters.bodyType
                ? "bg-cyan-500 text-black font-bold shadow-[0_0_10px_rgba(0,240,255,0.3)]"
                : "bg-slate-900/80 text-slate-400 border border-white/[0.08] hover:border-white/[0.2] hover:text-white"
            )}
          >
            All
          </button>
          {distinctBodyTypes.map((type) => {
            const isSelected = filters.bodyType === type;
            return (
              <button
                key={type}
                type="button"
                onClick={() =>
                  onChange({
                    ...filters,
                    bodyType: isSelected ? undefined : (type as VehicleBodyType),
                  })
                }
                className={cn(
                  "px-2.5 py-1 rounded-sm text-xs font-mono transition-colors",
                  isSelected
                    ? "bg-cyan-500 text-black font-bold shadow-[0_0_10px_rgba(0,240,255,0.3)]"
                    : "bg-slate-900/80 text-slate-400 border border-white/[0.08] hover:border-white/[0.2] hover:text-white"
                )}
              >
                {type}
              </button>
            );
          })}
        </div>
      </div>

      {/* 2. Fuel Type */}
      <div className="space-y-2.5">
        <label className="block font-mono text-xs font-semibold text-slate-300 uppercase tracking-wider">
          Fuel & Propulsion
        </label>
        <div className="flex flex-wrap gap-1.5">
          <button
            type="button"
            onClick={() => onChange({ ...filters, fuelType: undefined })}
            className={cn(
              "px-2.5 py-1 rounded-sm text-xs font-mono transition-colors",
              !filters.fuelType
                ? "bg-cyan-500 text-black font-bold shadow-[0_0_10px_rgba(0,240,255,0.3)]"
                : "bg-slate-900/80 text-slate-400 border border-white/[0.08] hover:border-white/[0.2] hover:text-white"
            )}
          >
            All
          </button>
          {distinctFuelTypes.map((fuel) => {
            const isSelected = filters.fuelType === fuel;
            return (
              <button
                key={fuel}
                type="button"
                onClick={() =>
                  onChange({
                    ...filters,
                    fuelType: isSelected ? undefined : (fuel as VehicleFuelType),
                  })
                }
                className={cn(
                  "px-2.5 py-1 rounded-sm text-xs font-mono transition-colors",
                  isSelected
                    ? "bg-cyan-500 text-black font-bold shadow-[0_0_10px_rgba(0,240,255,0.3)]"
                    : "bg-slate-900/80 text-slate-400 border border-white/[0.08] hover:border-white/[0.2] hover:text-white"
                )}
              >
                {fuel}
              </button>
            );
          })}
        </div>
      </div>

      {/* 3. Brand Selector */}
      <div className="space-y-2.5">
        <label className="block font-mono text-xs font-semibold text-slate-300 uppercase tracking-wider">
          Brand
        </label>
        <select
          value={filters.brand || "All"}
          onChange={(e) =>
            onChange({
              ...filters,
              brand: e.target.value === "All" ? undefined : e.target.value,
            })
          }
          className="w-full h-10 rounded-md border border-white/[0.10] bg-[#0A0E17] px-3 py-2 text-xs font-mono text-slate-200 focus:border-cyan-400 focus:outline-none"
        >
          <option value="All">All Brands ({distinctBrands.length})</option>
          {distinctBrands.map((brand) => (
            <option key={brand} value={brand}>
              {brand}
            </option>
          ))}
        </select>
      </div>

      {/* 4. Transmission */}
      <div className="space-y-2.5">
        <label className="block font-mono text-xs font-semibold text-slate-300 uppercase tracking-wider">
          Transmission
        </label>
        <div className="grid grid-cols-2 gap-1.5">
          {["All", "Automatic", "Dual-Clutch", "Manual", "Direct-Drive"].map((t) => {
            const isSelected =
              t === "All" ? !filters.transmission : filters.transmission === t;
            return (
              <button
                key={t}
                type="button"
                onClick={() =>
                  onChange({
                    ...filters,
                    transmission:
                      t === "All" ? undefined : (t as VehicleTransmission),
                  })
                }
                className={cn(
                  "px-2 py-1.5 rounded-sm text-xs font-mono text-center transition-colors border",
                  isSelected
                    ? "bg-[#0F1829] border-cyan-400/50 text-cyan-300 font-semibold shadow-[0_0_10px_rgba(0,240,255,0.15)]"
                    : "bg-[#0A0E17] border-white/[0.06] text-slate-400 hover:text-white"
                )}
              >
                {t}
              </button>
            );
          })}
        </div>
      </div>

      {/* 5. Price Range Slider */}
      <div className="space-y-3 pt-2 border-t border-white/[0.06]">
        <Slider
          label="Max Budget"
          min={priceBounds.min}
          max={priceBounds.max}
          step={5000}
          value={currentMaxPrice}
          onChange={(val) => onChange({ ...filters, maxPrice: val })}
          formatValue={(val) => formatCurrency(val)}
        />
      </div>

      {/* 6. Minimum Horsepower */}
      <div className="space-y-3 pt-2 border-t border-white/[0.06]">
        <Slider
          label="Min Horsepower"
          min={hpBounds.min}
          max={hpBounds.max}
          step={25}
          value={currentMinHp}
          onChange={(val) => onChange({ ...filters, minHorsepower: val })}
          unit="HP"
        />
      </div>

      {/* 7. Featured Filter */}
      <div className="pt-2 border-t border-white/[0.06]">
        <label className="flex items-center justify-between cursor-pointer p-2 rounded-md bg-[#0A0E17] border border-white/[0.06] hover:border-white/[0.12] transition-colors">
          <span className="font-mono text-xs text-slate-300 flex items-center gap-1.5">
            <Sparkles className="h-3.5 w-3.5 text-amber-400" />
            Featured Showcases Only
          </span>
          <input
            type="checkbox"
            checked={Boolean(filters.isFeatured)}
            onChange={(e) =>
              onChange({
                ...filters,
                isFeatured: e.target.checked ? true : undefined,
              })
            }
            className="rounded border-white/20 bg-slate-900 text-cyan-400 focus:ring-cyan-400 h-4 w-4"
          />
        </label>
      </div>
    </div>
  );

  return (
    <>
      {/* Desktop Sticky Sidebar */}
      <aside className="hidden lg:block w-72 flex-shrink-0">
        <div className="sticky top-24 rounded-lg border border-white/[0.08] bg-[#090D15]/80 backdrop-blur-md p-5 shadow-lg">
          {filterContent}
        </div>
      </aside>

      {/* Mobile Drawer / Modal */}
      <AnimatePresence>
        {isMobileOpen && (
          <>
            {/* Backdrop */}
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={onCloseMobile}
              className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm lg:hidden"
              aria-hidden="true"
            />

            {/* Slide-in Drawer */}
            <motion.div
              initial={{ x: "100%" }}
              animate={{ x: 0 }}
              exit={{ x: "100%" }}
              transition={SPRING_TRANSITION}
              className="fixed inset-y-0 right-0 z-50 w-full max-w-sm bg-[#080C14] border-l border-white/[0.10] p-6 shadow-2xl overflow-y-auto lg:hidden flex flex-col justify-between"
            >
              <div className="space-y-6">
                <div className="flex items-center justify-between pb-3 border-b border-white/[0.10]">
                  <h3 className="font-mono text-base font-bold uppercase text-white">
                    Filter Vehicles
                  </h3>
                  <button
                    type="button"
                    onClick={onCloseMobile}
                    className="p-1 rounded-sm text-slate-400 hover:text-white"
                    aria-label="Close filters drawer"
                  >
                    <X className="h-5 w-5" />
                  </button>
                </div>

                {filterContent}
              </div>

              <div className="pt-6 border-t border-white/[0.08] mt-6">
                <Button
                  variant="primary"
                  size="lg"
                  onClick={onCloseMobile}
                  className="w-full uppercase font-bold text-xs"
                >
                  Apply Filters
                </Button>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </>
  );
};

